
"""Display a summary of a JSON file generated by crawler.py."""

import argparse
import json
from pathlib import Path


def load_json(file_path):
    file_path = Path(file_path)

    if not file_path.is_file():
        raise SystemExit(f"File not found: {file_path}")

    try:
        with file_path.open("r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, json.JSONDecodeError) as error:
        raise SystemExit(f"Unable to read the JSON file: {error}")

    required_fields = (
        "url_source",
        "date_extraction",
        "titre",
        "paragraphes",
        "liens",
    )

    missing_fields = [
        field for field in required_fields if field not in data
    ]

    if missing_fields:
        raise SystemExit(
            "Incomplete JSON. Missing fields: "
            + ", ".join(missing_fields)
        )

    if (
        not isinstance(data["paragraphes"], list)
        or not isinstance(data["liens"], list)
    ):
        raise SystemExit(
            "Invalid JSON: 'paragraphes' and 'liens' must be lists."
        )

    return data


def main():
    parser = argparse.ArgumentParser(
        description="Browse a Chronos crawler JSON export offline."
    )

    parser.add_argument(
        "file",
        nargs="?",
        default="mansa_musa.json",
        help="Path to the JSON file",
    )

    parser.add_argument(
        "--paragraphs",
        type=int,
        default=5,
        help="Number of paragraphs to display (default: 5)",
    )

    parser.add_argument(
        "--links",
        type=int,
        default=5,
        help="Number of links to display (default: 5)",
    )

    args = parser.parse_args()
    data = load_json(args.file)

    links = data["liens"]

    internal_links = data.get(
        "liens_internes",
        [link for link in links if link.get("type") == "interne"],
    )

    external_links = data.get(
        "liens_externes",
        [link for link in links if link.get("type") == "externe"],
    )

    print("===== OFFLINE VIEWER =====")
    print("File:", Path(args.file).resolve())
    print("Title:", data.get("titre") or "(untitled)")
    print("Source URL:", data.get("url_source", ""))
    print("Extraction date:", data.get("date_extraction", "unknown"))
    print("Number of paragraphs:", len(data["paragraphes"]))
    print("Total number of links:", len(links))
    print("Internal links:", len(internal_links))
    print("External links:", len(external_links))

    print("\n===== H1 HEADINGS =====")

    for heading in data.get("titres_h1", []):
        print("-", heading)

    paragraph_count = max(0, args.paragraphs)

    print(f"\n===== FIRST {paragraph_count} PARAGRAPHS =====")

    for number, paragraph in enumerate(
        data["paragraphes"][:paragraph_count],
        start=1,
    ):
        print(f"\nParagraph {number}:\n{paragraph}")

    link_count = max(0, args.links)

    print(f"\n===== FIRST {link_count} LINKS =====")

    for link in links[:link_count]:
        link_type = link.get("type", "unknown")
        link_text = link.get("texte") or "(no text)"
        link_url = link.get("url", "")

        print(f"- [{link_type}] {link_text}: {link_url}")


if __name__ == "__main__":
    main()
